$ErrorActionPreference='Stop';$Repo=Split-Path -Parent $PSScriptRoot;Set-Location $Repo;$Py=Join-Path $Repo '.venv-nemotron\Scripts\python.exe';$H=Get-Content 'pro_research\results\S100_PHASE5_HELDOUT.json' -Raw|ConvertFrom-Json;$Green=@($H.results.PSObject.Properties|Where-Object{$_.Value.status-eq'v18_fidelity_candidate'}|ForEach-Object{$_.Name});if($Green.Count-eq 0){Write-Host 'No heldout-green phase5 candidates; timing skipped.';exit 0};foreach($C in $Green){Write-Host "=== timing $C ===" -ForegroundColor Cyan;foreach($R in @('base_a','cand_a','cand_b','base_b')){& $Py 'pro_research\s100_phase5_timing_arm.py' --candidate $C --role $R;if($LASTEXITCODE-ne 0){throw "timing $C/$R failed"}};& $Py 'pro_research\s100_phase5_timing_compare.py' --candidate $C;if($LASTEXITCODE-ne 0){throw "compare $C failed"}}
